export interface TextbookEdition {
  key: TextbookEditionKey
  name: string       // 版本名，如「外研版」
  desc: string       // 版本副注
  color: string
  maxGrade: number   // 版本年级上限（沪教 5 / PEP·外研 6）
  banks: Record<number, { up: TextbookKey; down: TextbookKey }>  // 年级 → 上/下册档位 key
}

